insert into `plantillas` (`id`, `tipo_documento_id`, `nombre`, `descripcion`, `activo`, `contenido_html`, `estructura`, `created_at`, `updated_at`) values (7, 1, 'Decreto alcaldicio (ejemplo)', 'Decreto con vistos, considerandos, resolutivos, doble firma y cadena de visaciones.', 1, '<p style="text-align:right">Santo Domingo, {{fecha}}</p><p><strong>MATERIA:</strong> Autoriza [materia del decreto] solicitado en el expediente {{expediente}}</p><p><strong>VISTOS:</strong></p><ol><li>Lo dispuesto en la Ley N° 18.695, Orgánica Constitucional de Municipalidades.</li><li>La Ley N° 19.880, que establece las bases de los procedimientos administrativos.</li><li>La solicitud folio {{folio}} ingresada en el trámite «{{tramite}}», expediente {{expediente}}.</li></ol><p><strong>CONSIDERANDO:</strong></p><ol><li>Que, [fundamento de hecho o de derecho que justifica la medida].</li><li>Que, la unidad {{unidad}} informó favorablemente la solicitud.</li></ol><p><strong>DECRETO:</strong></p><p>1.- <strong>AUTORÍZASE</strong> [describir lo que se autoriza o aprueba].</p><p>2.- <strong>IMPÚTESE</strong> el gasto que corresponda, si lo hubiere, al ítem presupuestario respectivo.</p><p>3.- <strong>NOTIFÍQUESE</strong> la presente resolución a quien corresponda.</p><p>ANÓTESE, COMUNÍQUESE Y ARCHÍVESE.</p><table style="width:100%;border-collapse:collapse;margin-top:24px"><tbody><tr><td style="text-align:center;width:50%"><p>&nbsp;</p><p>&nbsp;</p><p><strong>ALCALDE(SA)</strong></p></td><td style="text-align:center;width:50%"><p>&nbsp;</p><p>&nbsp;</p><p><strong>SECRETARIO(A) MUNICIPAL</strong></p></td></tr></tbody></table><p style="font-size:9pt;margin-top:18px"><strong>Cadena de responsabilidad (visaciones):</strong> {{cadena_iniciales}}</p><table style="font-size:9pt;border-collapse:collapse;border:1px solid #999;width:60%"><thead><tr><th style="border:1px solid #999;padding:2px 6px;text-align:left">Cargo</th><th style="border:1px solid #999;padding:2px 6px">Iniciales</th></tr></thead><tbody><tr><td style="border:1px solid #999;padding:2px 6px">Director(a) de Obras Municipales</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_1}}</td></tr><tr><td style="border:1px solid #999;padding:2px 6px">Asesor(a) Jurídico(a)</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_2}}</td></tr><tr><td style="border:1px solid #999;padding:2px 6px">Secretario(a) Municipal</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_3}}</td></tr></tbody></table>', '{"materia":"Autoriza [materia del decreto] solicitado en el expediente {{expediente}}","cuerpo_tipo":"decreto","vistos":["Lo dispuesto en la Ley N° 18.695, Orgánica Constitucional de Municipalidades.","La Ley N° 19.880, que establece las bases de los procedimientos administrativos.","La solicitud folio {{folio}} ingresada en el trámite «{{tramite}}», expediente {{expediente}}."],"considerando":["Que, [fundamento de hecho o de derecho que justifica la medida].","Que, la unidad {{unidad}} informó favorablemente la solicitud."],"cuerpo_html":"<p>1.- <strong>AUTORÍZASE<\\/strong> [describir lo que se autoriza o aprueba].<\\/p><p>2.- <strong>IMPÚTESE<\\/strong> el gasto que corresponda, si lo hubiere, al ítem presupuestario respectivo.<\\/p><p>3.- <strong>NOTIFÍQUESE<\\/strong> la presente resolución a quien corresponda.<\\/p>","firmas":[{"cargo":"Alcalde(sa)","rol":"alcalde"},{"cargo":"Secretario(a) Municipal","rol":"secretario"}],"cadena":[{"cargo":"Director(a) de Obras Municipales","usuario_id":null},{"cargo":"Asesor(a) Jurídico(a)","usuario_id":null},{"cargo":"Secretario(a) Municipal","usuario_id":null}],"cierre":"ANÓTESE, COMUNÍQUESE Y ARCHÍVESE."}', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
insert into `plantillas` (`id`, `tipo_documento_id`, `nombre`, `descripcion`, `activo`, `contenido_html`, `estructura`, `created_at`, `updated_at`) values (8, 3, 'Oficio ordinario (ejemplo)', 'Oficio de respuesta con antecedentes, fundamentos y una firma.', 1, '<p style="text-align:right">Santo Domingo, {{fecha}}</p><p><strong>MAT.:</strong> Responde la solicitud folio {{folio}}</p><p><strong>ANT.:</strong></p><ol><li>Solicitud folio {{folio}} presentada por {{solicitante_nombre}} en el trámite «{{tramite}}».</li><li>Expediente {{expediente}}.</li></ol><p><strong>CONSIDERANDO:</strong></p><ol><li>Que, la solicitud fue revisada por {{unidad}}.</li></ol><p><strong>OFICIO</strong></p><p>De mi consideración:</p><p>Junto con saludar, y en respuesta a la solicitud individualizada en los antecedentes, informo a usted que [detalle de la respuesta].</p><p>Saluda atentamente a Ud.,</p><table style="width:100%;border-collapse:collapse;margin-top:24px"><tbody><tr><td style="text-align:center;width:100%"><p>&nbsp;</p><p>&nbsp;</p><p><strong>DIRECTOR(A) DE LA UNIDAD</strong></p></td></tr></tbody></table><p style="font-size:9pt;margin-top:18px"><strong>Cadena de responsabilidad (visaciones):</strong> {{cadena_iniciales}}</p><table style="font-size:9pt;border-collapse:collapse;border:1px solid #999;width:60%"><thead><tr><th style="border:1px solid #999;padding:2px 6px;text-align:left">Cargo</th><th style="border:1px solid #999;padding:2px 6px">Iniciales</th></tr></thead><tbody><tr><td style="border:1px solid #999;padding:2px 6px">Director(a) de Obras Municipales</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_1}}</td></tr></tbody></table>', '{"materia":"Responde la solicitud folio {{folio}}","cuerpo_tipo":"oficio","vistos":["Solicitud folio {{folio}} presentada por {{solicitante_nombre}} en el trámite «{{tramite}}».","Expediente {{expediente}}."],"considerando":["Que, la solicitud fue revisada por {{unidad}}."],"cuerpo_html":"<p>De mi consideración:<\\/p><p>Junto con saludar, y en respuesta a la solicitud individualizada en los antecedentes, informo a usted que [detalle de la respuesta].<\\/p>","firmas":[{"cargo":"Director(a) de la unidad","rol":"funcionario"}],"cadena":[{"cargo":"Director(a) de Obras Municipales","usuario_id":null}],"cierre":"Saluda atentamente a Ud.,"}', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
insert into `plantillas` (`id`, `tipo_documento_id`, `nombre`, `descripcion`, `activo`, `contenido_html`, `estructura`, `created_at`, `updated_at`) values (9, 4, 'Ordenanza municipal (ejemplo)', 'Ordenanza con título, artículos y publicación.', 1, '<p style="text-align:right">Santo Domingo, {{fecha}}</p><p><strong>MATERIA:</strong> Ordenanza sobre [materia regulada]</p><p><strong>VISTOS:</strong></p><ol><li>Lo dispuesto en la Ley N° 18.695, Orgánica Constitucional de Municipalidades.</li><li>El acuerdo del Concejo Municipal adoptado en la sesión [N°] de fecha [fecha].</li></ol><p><strong>CONSIDERANDO:</strong></p><ol><li>Que, es necesario regular [materia] en la comuna.</li></ol><p><strong>ORDENANZA:</strong></p><p><strong>TÍTULO I — DISPOSICIONES GENERALES</strong></p><p><strong>Artículo 1°.-</strong> [Objeto de la ordenanza].</p><p><strong>Artículo 2°.-</strong> [Ámbito de aplicación].</p><p><strong>TÍTULO II — [NOMBRE]</strong></p><p><strong>Artículo 3°.-</strong> [Texto].</p><p>ANÓTESE, COMUNÍQUESE, PUBLÍQUESE Y ARCHÍVESE.</p><table style="width:100%;border-collapse:collapse;margin-top:24px"><tbody><tr><td style="text-align:center;width:50%"><p>&nbsp;</p><p>&nbsp;</p><p><strong>ALCALDE(SA)</strong></p></td><td style="text-align:center;width:50%"><p>&nbsp;</p><p>&nbsp;</p><p><strong>SECRETARIO(A) MUNICIPAL</strong></p></td></tr></tbody></table><p style="font-size:9pt;margin-top:18px"><strong>Cadena de responsabilidad (visaciones):</strong> {{cadena_iniciales}}</p><table style="font-size:9pt;border-collapse:collapse;border:1px solid #999;width:60%"><thead><tr><th style="border:1px solid #999;padding:2px 6px;text-align:left">Cargo</th><th style="border:1px solid #999;padding:2px 6px">Iniciales</th></tr></thead><tbody><tr><td style="border:1px solid #999;padding:2px 6px">Director(a) de Obras Municipales</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_1}}</td></tr><tr><td style="border:1px solid #999;padding:2px 6px">Asesor(a) Jurídico(a)</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_2}}</td></tr><tr><td style="border:1px solid #999;padding:2px 6px">Secretario(a) Municipal</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_3}}</td></tr></tbody></table>', '{"materia":"Ordenanza sobre [materia regulada]","cuerpo_tipo":"ordenanza","vistos":["Lo dispuesto en la Ley N° 18.695, Orgánica Constitucional de Municipalidades.","El acuerdo del Concejo Municipal adoptado en la sesión [N°] de fecha [fecha]."],"considerando":["Que, es necesario regular [materia] en la comuna."],"cuerpo_html":"<p><strong>TÍTULO I — DISPOSICIONES GENERALES<\\/strong><\\/p><p><strong>Artículo 1°.-<\\/strong> [Objeto de la ordenanza].<\\/p><p><strong>Artículo 2°.-<\\/strong> [Ámbito de aplicación].<\\/p><p><strong>TÍTULO II — [NOMBRE]<\\/strong><\\/p><p><strong>Artículo 3°.-<\\/strong> [Texto].<\\/p>","firmas":[{"cargo":"Alcalde(sa)","rol":"alcalde"},{"cargo":"Secretario(a) Municipal","rol":"secretario"}],"cadena":[{"cargo":"Director(a) de Obras Municipales","usuario_id":null},{"cargo":"Asesor(a) Jurídico(a)","usuario_id":null},{"cargo":"Secretario(a) Municipal","usuario_id":null}],"cierre":"ANÓTESE, COMUNÍQUESE, PUBLÍQUESE Y ARCHÍVESE."}', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
insert into `plantillas` (`id`, `tipo_documento_id`, `nombre`, `descripcion`, `activo`, `contenido_html`, `estructura`, `created_at`, `updated_at`) values (10, 5, 'Reglamento interno (ejemplo)', 'Reglamento con capítulos y artículos.', 1, '<p style="text-align:right">Santo Domingo, {{fecha}}</p><p><strong>MATERIA:</strong> Aprueba el reglamento de [materia]</p><p><strong>VISTOS:</strong></p><ol><li>Lo dispuesto en la Ley N° 18.695, Orgánica Constitucional de Municipalidades.</li></ol><p><strong>CONSIDERANDO:</strong></p><ol><li>Que, se requiere un marco claro de funcionamiento para [materia].</li></ol><p><strong>REGLAMENTO:</strong></p><p><strong>CAPÍTULO I — NORMAS GENERALES</strong></p><p><strong>Artículo 1°.-</strong> [Objeto].</p><p><strong>CAPÍTULO II — [NOMBRE]</strong></p><p><strong>Artículo 2°.-</strong> [Texto].</p><p>ANÓTESE, COMUNÍQUESE Y ARCHÍVESE.</p><table style="width:100%;border-collapse:collapse;margin-top:24px"><tbody><tr><td style="text-align:center;width:50%"><p>&nbsp;</p><p>&nbsp;</p><p><strong>ALCALDE(SA)</strong></p></td><td style="text-align:center;width:50%"><p>&nbsp;</p><p>&nbsp;</p><p><strong>SECRETARIO(A) MUNICIPAL</strong></p></td></tr></tbody></table><p style="font-size:9pt;margin-top:18px"><strong>Cadena de responsabilidad (visaciones):</strong> {{cadena_iniciales}}</p><table style="font-size:9pt;border-collapse:collapse;border:1px solid #999;width:60%"><thead><tr><th style="border:1px solid #999;padding:2px 6px;text-align:left">Cargo</th><th style="border:1px solid #999;padding:2px 6px">Iniciales</th></tr></thead><tbody><tr><td style="border:1px solid #999;padding:2px 6px">Director(a) de Obras Municipales</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_1}}</td></tr><tr><td style="border:1px solid #999;padding:2px 6px">Asesor(a) Jurídico(a)</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_2}}</td></tr><tr><td style="border:1px solid #999;padding:2px 6px">Secretario(a) Municipal</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_3}}</td></tr></tbody></table>', '{"materia":"Aprueba el reglamento de [materia]","cuerpo_tipo":"reglamento","vistos":["Lo dispuesto en la Ley N° 18.695, Orgánica Constitucional de Municipalidades."],"considerando":["Que, se requiere un marco claro de funcionamiento para [materia]."],"cuerpo_html":"<p><strong>CAPÍTULO I — NORMAS GENERALES<\\/strong><\\/p><p><strong>Artículo 1°.-<\\/strong> [Objeto].<\\/p><p><strong>CAPÍTULO II — [NOMBRE]<\\/strong><\\/p><p><strong>Artículo 2°.-<\\/strong> [Texto].<\\/p>","firmas":[{"cargo":"Alcalde(sa)","rol":"alcalde"},{"cargo":"Secretario(a) Municipal","rol":"secretario"}],"cadena":[{"cargo":"Director(a) de Obras Municipales","usuario_id":null},{"cargo":"Asesor(a) Jurídico(a)","usuario_id":null},{"cargo":"Secretario(a) Municipal","usuario_id":null}],"cierre":"ANÓTESE, COMUNÍQUESE Y ARCHÍVESE."}', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
insert into `plantillas` (`id`, `tipo_documento_id`, `nombre`, `descripcion`, `activo`, `contenido_html`, `estructura`, `created_at`, `updated_at`) values (11, 6, 'Instructivo (ejemplo)', 'Instructivo interno con instrucciones numeradas.', 1, '<p style="text-align:right">Santo Domingo, {{fecha}}</p><p><strong>MATERIA:</strong> Instruye sobre [materia]</p><p><strong>CONSIDERANDO:</strong></p><ol><li>Que, es necesario uniformar el procedimiento de [materia].</li></ol><p><strong>INSTRUCTIVO:</strong></p><p>1.- Las unidades municipales deberán [instrucción].</p><p>2.- El plazo para dar cumplimiento será de [N] días hábiles.</p><p>3.- Las consultas se dirigirán a [unidad o cargo].</p><p>Se instruye dar estricto cumplimiento a lo dispuesto.</p><table style="width:100%;border-collapse:collapse;margin-top:24px"><tbody><tr><td style="text-align:center;width:100%"><p>&nbsp;</p><p>&nbsp;</p><p><strong>ALCALDE(SA)</strong></p></td></tr></tbody></table><p style="font-size:9pt;margin-top:18px"><strong>Cadena de responsabilidad (visaciones):</strong> {{cadena_iniciales}}</p><table style="font-size:9pt;border-collapse:collapse;border:1px solid #999;width:60%"><thead><tr><th style="border:1px solid #999;padding:2px 6px;text-align:left">Cargo</th><th style="border:1px solid #999;padding:2px 6px">Iniciales</th></tr></thead><tbody><tr><td style="border:1px solid #999;padding:2px 6px">Secretario(a) Municipal</td><td style="border:1px solid #999;padding:2px 6px;text-align:center">{{cadena_1}}</td></tr></tbody></table>', '{"materia":"Instruye sobre [materia]","cuerpo_tipo":"instructivo","vistos":[],"considerando":["Que, es necesario uniformar el procedimiento de [materia]."],"cuerpo_html":"<p>1.- Las unidades municipales deberán [instrucción].<\\/p><p>2.- El plazo para dar cumplimiento será de [N] días hábiles.<\\/p><p>3.- Las consultas se dirigirán a [unidad o cargo].<\\/p>","firmas":[{"cargo":"Alcalde(sa)","rol":"alcalde"}],"cadena":[{"cargo":"Secretario(a) Municipal","usuario_id":null}],"cierre":"Se instruye dar estricto cumplimiento a lo dispuesto."}', '2026-01-01 00:00:00', '2026-01-01 00:00:00');
insert into `delegaciones_firma` (`id`, `tipo_documento_id`, `delegado_id`, `decreto_referencia`, `vigente_desde`, `vigente_hasta`, `creado_por`, `activo`, `created_at`, `updated_at`) values (1, 1, 8, 'Decreto Alcaldicio N° 123/2026 (DEMO)', '2026-01-01', '2026-12-31', 2, 1, '2026-01-01 00:00:00', '2026-01-01 00:00:00');
